def format_array_flat(array, max_width):
    """Format an array on one line, truncating its middle as needed."""
    size = array.size
    if size == 0:
        return ""
    max_items = max(1, min(size, max_width // 2 + 1))
    front = format_items(first_n_items(array, max_items))
    if size <= max_items:
        return maybe_truncate(" ".join(front), max_width)
    back = format_items(last_n_items(array, max_items))

    best = "..."
    for total in range(2, 2 * max_items + 1):
        n_front = (total + 1) // 2
        n_back = total // 2
        if n_front + n_back >= size:
            candidate = " ".join(format_items(first_n_items(array, size)))
        else:
            candidate = " ".join(front[:n_front] + ["..."] + back[-n_back:])
        if len(candidate) <= max_width:
            best = candidate
        else:
            # Later candidates are no shorter in the normal case.
            continue
    if best == "...":
        if max_width < 3:
            return "..."
        return maybe_truncate(f"{front[0]} ... {back[-1]}", max_width)
    return maybe_truncate(best, max_width)

