def _advanced_indexer_subspaces(key):
    advanced = [i for i, value in enumerate(key) if not isinstance(value, slice)]
    if not advanced:
        return (), ()
    arrays = [np.asarray(key[i]) for i in advanced]
    ndim = len(np.broadcast_shapes(*(array.shape for array in arrays)))
    contiguous = advanced == list(range(advanced[0], advanced[-1] + 1))
    if contiguous:
        mixed = tuple(range(advanced[0], advanced[0] + ndim))
    else:
        mixed = tuple(range(ndim))
    return mixed, tuple(range(ndim))


